#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
using namespace std;

int main(){
    vector<double>equity={100,110,105,95,102},returns={0.02,0.01,-0.04,-0.03,0.02};
    double peak=equity[0],worst=0,mean=0;
    for (double v:equity){
        peak=max(peak,v);
        worst=min(worst,v/peak-1);
    }
    for (double r:returns)mean+=r/returns.size();
    double utility=mean-0.5*fabs(worst);
    cout<<mean<<" "<<worst<<" "<<utility<<"\n";
    return 0;
}

