#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
#include <utility>
using namespace std;

int main(){
    vector<pair<int,int>>interval={{1,4},{2,5},{4,6}};
    for (int i=0;i<int(interval.size());i++){
        double uniqueness=0;
        int count=0;
        for (int t=interval[i].first;t<=interval[i].second;t++){
            int concurrent=0;
            for (const auto& e:interval)if (e.first<=t&&t<=e.second)concurrent++;
            uniqueness+=1.0/concurrent;
            count++;
        }
        cout<<i<<" "<<uniqueness/count<<"\n";
    }
    return 0;
}

